function lovr.load()
  model = lovr.graphics.newModel('model.glb')
  lovr.graphics.setBackgroundColor(.2, .2, .22)

  shader = lovr.graphics.newShader('unlit', [[
    uniform raytracer tracer;
    uniform vec3 lightPosition;

    vec4 lovrmain() {
      vec4 color = DefaultColor;
      vec3 L = lightPosition - PositionWorld;
      vec3 rayPos = PositionWorld + normalize(Normal) * .01;
      vec3 rayDir = L;

      rayQueryEXT ray;
      float tmin = .001, tmax = 1.0;
      uint flags = gl_RayFlagsTerminateOnFirstHitEXT;
      rayQueryInitializeEXT(ray, tracer, flags, 0xff, rayPos, tmin, rayDir, tmax);
      rayQueryProceedEXT(ray);

      if (rayQueryGetIntersectionTypeEXT(ray, true) == gl_RayQueryCommittedIntersectionNoneEXT) {
        return vec4(color.rgb, 1.);
      } else {
        return vec4(color.rgb * .05, color.a);
      }
    }
  ]])

  raytracer = lovr.graphics.newRaytracer(1)
  raytracer:add(model, 0, 0, 0, .01)
end

function lovr.update(dt)
  model:resetNodeTransforms()
  model:animate(1, lovr.timer.getTime())
  model:buildRaytracer()
  raytracer:build()
end

function lovr.draw(pass)
  pass:setShader(shader)
  pass:send('tracer', raytracer)
  pass:send('lightPosition', 5, 5, 5)

  pass:setColor(0x664455)
  pass:plane(0, 0, 0, 10, 10, math.pi / 2, 1, 0, 0)

  pass:setColor(0xffffff)
  pass:draw(model, 0, 0, 0, .01)
end

shader = lovr.graphics.newShader([[
  uniform Transforms {
    mat4 transforms[32];
  };

  vec4 lovrmain() {
    return Projection * View * transforms[InstanceIndex] * VertexPosition;
  }
]], 'unlit')

local format, length = shader:getBufferFormat('Transforms')
print(length) --> 32
print(format[1].name) --> 'transforms'
print(format[1].type) --> 'mat4'

-- Can pass the 2 results directly to newBuffer:
transforms = lovr.graphics.newBuffer(shader:getBufferFormat('Transforms'))

-- Or override the length with some initial data:
transforms = lovr.graphics.newBuffer(shader:getBufferFormat('Transforms'), objects)

methods.notes:
If the buffer only has a single array field, the format will be "unwrapped" to an array instead of a single-field struct with an array in it.  Example:

    shader = lovr.graphics.newShader([[
      buffer Numbers {
        uint numbers[64];
      };

      void lovrmain(){}
    ]])

    shader:getBufferFormat('Numbers')
    -- returns {{ name = 'numbers', type = 'u32' }}, 64
    -- not     {{ name = 'numbers', type = 'u32', length = 64 }}, 1

Similarly, if the buffer only has a single struct field, the format will be "unwrapped" to the inner struct.  This lets you use a struct for a Buffer's data without having to wrap everything in an extra namespace.  Example:

    shader = lovr.graphics.newShader([[
      struct HandParams {
        vec3 pos;
        float grip;
      };

      buffer Hand {
        HandParams params;
      };

      void lovrmain(){}
    ]])

    shader:getBufferFormat('Hand')
    -- returns {{ name = 'pos', type = 'vec3' }, { name = 'grip', type = 'float' }}, 1
    -- not     {{ name = 'params', type = {...}}}, 1

